#include "screenshader.h"

#include <QCoreApplication>
#include <QDir>
#include <QJsonArray>
#include <QJsonObject>
#include <QSaveFile>
#include <QStandardPaths>

#include <cmath>

#include "hypripc.h"
#include "wmstate.h"

namespace {

const QString shaderOption = QStringLiteral("decoration:screen_shader");

bool neutral(double v)
{
    return std::fabs(v - 1.0) < 0.005;
}

/* BT.709 luma, the weights libvibrant's matrix is built from, so a
 * saturation looks as it does under X11. */
const char *preamble =
    "#version 300 es\n"
    "/* Generated by fanshell-qs-shell (screenshader.h). Edits are lost. */\n"
    "precision highp float;\n"
    "in vec2 v_texcoord;\n"
    "uniform sampler2D tex;\n"
    "uniform int wl_output;\n"
    "layout(location = 0) out vec4 fragColor;\n"
    "\n"
    "vec3 saturate(vec3 c, float s) {\n"
    "    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));\n"
    "    return clamp(vec3(l) + (c - vec3(l)) * s, 0.0, 1.0);\n"
    "}\n"
    "\n"
    "void main() {\n"
    "    vec4 px = texture(tex, v_texcoord);\n";

} /* namespace */

ScreenShader *ScreenShader::instance()
{
    static ScreenShader *s = new ScreenShader();
    return s;
}

ScreenShader::ScreenShader(QObject *parent) : QObject(parent)
{
    /* A drag of the vibrance slider, or a night-light fade step, sets
     * values faster than Hyprland needs to recompile: once per turn. */
    m_write.setSingleShot(true);
    m_write.setInterval(30);
    connect(&m_write, &QTimer::timeout, this, &ScreenShader::write);
    /* Monitor ids change with hotplug, and a reload resets the option. */
    WmState *wm = WmState::instance();
    connect(wm, &WmState::outputsChanged, this, &ScreenShader::schedule);
    connect(wm, &WmState::configReloaded, this, [this]() {
        m_ours = false;
        schedule();
    });
    /* Leave the screen as it was for whatever runs after the shell. */
    connect(qApp, &QCoreApplication::aboutToQuit, this, [this]() {
        m_saturation.clear();
        m_gain[0] = m_gain[1] = m_gain[2] = 1.0;
        write();
    });
}

QString ScreenShader::path() const
{
    QString dir = QStandardPaths::writableLocation(QStandardPaths::RuntimeLocation);
    if (dir.isEmpty())
        dir = QDir::tempPath();
    return dir + QStringLiteral("/fanshell-qs/screen.frag");
}

void ScreenShader::setSaturation(const QString &output, double saturation)
{
    if (neutral(saturation))
        m_saturation.remove(output);
    else
        m_saturation.insert(output, saturation);
    schedule();
}

void ScreenShader::setGain(double r, double g, double b)
{
    m_gain[0] = r;
    m_gain[1] = g;
    m_gain[2] = b;
    schedule();
}

void ScreenShader::schedule()
{
    if (!m_write.isActive())
        m_write.start();
}

void ScreenShader::write()
{
    if (!HyprIpc::available())
        return;
    const bool warm = !neutral(m_gain[0]) || !neutral(m_gain[1]) || !neutral(m_gain[2]);

    /* Each saturated output that is connected now, by Hyprland's id. */
    QString branches;
    for (const QJsonValue &v : HyprIpc::requestArray("monitors")) {
        const QJsonObject o = v.toObject();
        const QString name = o.value(QStringLiteral("name")).toString();
        const auto it = m_saturation.constFind(name);
        if (it == m_saturation.constEnd())
            continue;
        branches += QStringLiteral("    %1if (wl_output == %2) /* %3 */\n"
                                   "        px.rgb = saturate(px.rgb, %4);\n")
                        .arg(branches.isEmpty() ? QString() : QStringLiteral("else "))
                        .arg(o.value(QStringLiteral("id")).toInt())
                        .arg(name)
                        .arg(*it, 0, 'f', 4);
    }

    const QString current = HyprIpc::optionValue(shaderOption).toString();
    const bool showing = !current.isEmpty() && current == path();
    if (branches.isEmpty() && !warm) {
        /* Nothing to do: hand the slot back. */
        if (showing)
            HyprIpc::setOption(shaderOption, m_foreign);
        m_ours = false;
        QFile::remove(path());
        return;
    }
    /* One screen shader slot: remember someone else's, to put it back. */
    if (!showing && !current.isEmpty())
        m_foreign = current;

    QString text = QString::fromLatin1(preamble);
    text += branches;
    if (warm)
        text += QStringLiteral("    px.rgb *= vec3(%1, %2, %3);\n")
                    .arg(m_gain[0], 0, 'f', 4)
                    .arg(m_gain[1], 0, 'f', 4)
                    .arg(m_gain[2], 0, 'f', 4);
    text += QStringLiteral("    fragColor = px;\n}\n");

    QDir().mkpath(QFileInfo(path()).absolutePath());
    /* Replaced atomically: Hyprland may read it at any moment. */
    QSaveFile file(path());
    if (!file.open(QIODevice::WriteOnly) || file.write(text.toUtf8()) < 0
            || !file.commit()) {
        qWarning("fanshell-qs: cannot write %s", qPrintable(path()));
        return;
    }

    /* Setting the option re-reads the file even when the path is the same.
     * Hyprland does not count a shader change as damage, and redraws only
     * two full frames of a three-buffer swapchain, so the third would keep
     * the old colours where nothing else redraws; writing border_size back
     * alongside (unchanged) damages the whole monitor (hyprvibrance's
     * finding). */
    QVector<QPair<QString, QVariant>> opts{{shaderOption, path()}};
    const QVariant border = HyprIpc::optionValue(QStringLiteral("general:border_size"));
    if (border.isValid())
        opts.push_back({QStringLiteral("general:border_size"), border.toLongLong()});
    m_ours = HyprIpc::setOptions(opts);
}
